sited.script:

function home_parse(url, html) {
    const $ = cheerio.load(html);
    var list = [], groups = [];

    // 2. 取得所有分類標題
    $('.title_h2').each(function() {
        groups.push($(this).text().trim().replace(/[\n\r\t]*/g, ""));
    });

    $('.gallary_wrap').each(function(index) {
        var $$ = cheerio.load($(this).html());
        const groupName = groups[index];

        $$('.pic_box').each(function() {
            var $$$ = cheerio.load($$(this).html());
            const linkElement = $$$('a'); // 'this' 是當前的 'a' 標籤
            const itemTitle = linkElement.attr('title')?.trim(); // ?. 可避免 title 不存在時報錯
            const itemUrl = linkElement.attr('href');
            const imgSrc = $$$('img').attr('src');

            list.push({
                group: gbk2big5.traditionalized(groupName),
                name: gbk2big5.traditionalized(itemTitle),
                logo: 'https:' + imgSrc,
                url: "https://www.wnacg.com" + itemUrl
            });
        });
    });

    return JSON.stringify(list);
}

function list_parse(url, html) {
    const $ = cheerio.load(html);
    var list = [];

    $('.gallary_wrap').each(function(index) {
        var $$ = cheerio.load($(this).html());

        $$('.pic_box').each(function() {
            var $$$ = cheerio.load($$(this).html());
            const linkElement = $$$('a'); // 'this' 是當前的 'a' 標籤
            const itemTitle = linkElement.attr('title')?.trim(); // ?. 可避免 title 不存在時報錯
            const itemUrl = linkElement.attr('href');
            const imgSrc = $$$('img').attr('src');

            list.push({
                name: gbk2big5.traditionalized(itemTitle),
                logo: 'https:' + imgSrc,
                url: "https://www.wnacg.com" + itemUrl
            });
        });
    });

    return JSON.stringify(list);
}

function book_parse_url(url, html) {
    const $ = cheerio.load(html);
    let maxPage = 1;

    $('.paginator a').each(function() {
        const p = parseInt($(this).text(), 10);

        if (!isNaN(p) && p > maxPage) {
            maxPage = p;
        }
    });

    var urls = [];
    for (let j = 1; j <= maxPage; j++) {
        urls.push(url.replace('.html', `-page-${j}.html`));
    }

    return JSON.stringify(urls);
}

function book_parse_api_response(url, html) {
    const $ = cheerio.load(html);

    const sections = [];
    $(".gallary_item").each(function(){
        const $$ = cheerio.load($(this).html());
        const sectionName = $$('.name', this).text().trim();
        const sectionUrl = $$('a', this).attr("href");

        // 確保成功取到值再 push
        if (sectionName && sectionUrl) {
            sections.push({
                name: sectionName,
                url: 'https://www.wnacg.com' + sectionUrl
            });
        }
    });

    const book = {
        name: gbk2big5.traditionalized($("h2").text().trim()),
        logo: 'https:' + $(".userwrap .uwthumb img").attr("src"),
        sections: sections
    };

    return JSON.stringify(book);
}

function section_parse(url, html) {
    const $ = cheerio.load(html);

    const data = $("#imgarea img").map(function() {
        const src = $(this).attr('src');
        if (src) {
            return {
                t: "image",
                d: 'https:' + src
            };
        }
    }).get();

    return JSON.stringify({
        type: "article",
        data: data
    });
}
